const $=id=>document.getElementById(id);let current=null,running=false,busy=false,catalog=[];
async function request(path,body){const res=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await res.json();if(!res.ok)throw Error(data.error);return data;}
function draw(data){current=data;$('board').textContent=data.frame;const o=data.observation,l=catalog.find(l=>l.id===o.scenario);$('scenario').textContent=`${l?.label??''} / ${l?.name??o.scenario} · ${o.scenario} · seed ${data.seed}`;$('status').textContent=`${data.result} · tick ${data.binding.tick} · observed t${o.tick} · TRAINING_STATUS=INACTIVE · ACTIVE_CONTROLLER=${data.activeController}`;
 $('hud').textContent=JSON.stringify({difficulty:l?.label,scenario:o.scenario,seed:data.seed,controller:data.controller,canonicalExpertsInvoked:data.decision?.canonicalExpertsInvoked??[],actualActionSource:data.decision?.actionSource??'NONE_YET',mode:'ISOLATED_DEVELOPMENT_PLAY',modelVersion:data.decision?.modelId??'NONE_ACTIVE',memory:data.decision?.memoryStatus??'WITHIN_EPISODE_ONLY',objectiveProgress:data.metrics.objectiveCompletion,resources:o.inventory??{health:o.health??o.actor?.health,supplies:o.supplies,credits:o.credits,clues:o.clues,errors:o.errors},catastrophic:data.metrics.catastrophic,repeatedFailures:data.metrics.repeatedFailures,lastAction:data.decision?.action,episodeOutcome:data.result,failureReason:data.terminal&&!data.metrics.success?data.result:null,trainedCandidate:data.trainedCandidate,qualification:data.levelStatus},null,2);
 $('inspector').textContent=JSON.stringify(data.decision??{canonicalExpertsInvoked:[],actualActionSource:'NONE_YET',expertComplementarity:'NOT_TESTABLE'},null,2);const old=$('action').value;$('action').replaceChildren(...data.actions.map(a=>{const op=document.createElement('option');op.value=a.id;op.textContent=a.type+' '+JSON.stringify(a.parameters);return op;}));if(data.actions.some(a=>a.id===old))$('action').value=old;if(data.terminal){running=false;$('play').textContent='Play Sentinel';}}
async function reset(){running=false;$('play').textContent='Play Sentinel';if(busy)return;busy=true;try{draw(await request('/api/reset',{session:current?.session,game:$('game').value,tier:Number($('tier').value),seed:Number($('seed').value),controller:$('controller').value,sensor:$('sensor').value}));}catch(e){$('status').textContent=e.message;}finally{busy=false;}}
async function advance(auto=true,actionId=null,batch=1){if(busy||!current||current.terminal)return;busy=true;try{draw(await request('/api/step',{session:current.session,binding:current.binding,auto,actionId,batch}));}catch(e){running=false;$('status').textContent='ERROR: '+e.message;$('play').textContent='Play Sentinel';}finally{busy=false;}}
$('reset').onclick=reset;for(const id of ['game','tier','controller','sensor'])$(id).onchange=reset;$('play').onclick=()=>{running=!running;$('play').textContent=running?'Pause':'Play Sentinel';};$('step').onclick=()=>advance();$('manual').onclick=()=>{running=false;$('play').textContent='Play Sentinel';advance(false,$('action').value);};$('fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.body.requestFullscreen();setInterval(()=>{if(running)advance(true,null,8);},90);
window.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(e.target.tagName)||running||!current)return;const map={pong:{ArrowUp:'UP',ArrowDown:'DOWN',' ':'HOLD'},platformer:{ArrowLeft:'MOVE_LEFT',ArrowRight:'MOVE_RIGHT',' ':'JUMP_RIGHT'},racing:{ArrowUp:'ACCELERATE',ArrowDown:'BRAKE',ArrowLeft:'TURN_LEFT',ArrowRight:'TURN_RIGHT'},fighter:{ArrowRight:'WALK_FORWARD',ArrowLeft:'WALK_BACK',' ':'JUMP_FORWARD',j:'LIGHT_ATTACK',k:'LOW_ATTACK',l:'BLOCK_HIGH'}},t=map[current.observation.game]?.[e.key]??({w:'MOVE_NORTH',s:'MOVE_SOUTH',a:'MOVE_WEST',d:'MOVE_EAST',' ':'WAIT'}[e.key]),a=current.actions.find(a=>a.type===t);if(a){e.preventDefault();advance(false,a.id);}});
catalog=(await(await fetch('/api/catalog')).json()).levels;await reset();
